/* .rgxsite package loader: SHA3 integrity, then declarative UI render. */
#include "rgxsite.h"
#include "rogex_core.h"   /* rogex_sha3_256 */
#include "desktop.h"

/* Embedded built-in sites (generated by scripts/rgxpack.py). */
#include "site_social.h"

#define HDR_SIZE   124
#define DESC_SIZE  88
#define ANAME_MAX  48
#define MAX_ASSETS 64

static uint16_t rd16(const uint8_t *p) { return (uint16_t)p[0] | ((uint16_t)p[1] << 8); }
static uint32_t rd32(const uint8_t *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}
static bool mem_eq(const uint8_t *a, const uint8_t *b, size_t n) {
    for (size_t i = 0; i < n; i++) if (a[i] != b[i]) return false;
    return true;
}

const char *rgxsite_status_str(rgxsite_status s) {
    switch (s) {
    case RGXSITE_OK:             return "ok";
    case RGXSITE_BAD_MAGIC:      return "bad magic";
    case RGXSITE_BAD_VERSION:    return "bad version";
    case RGXSITE_TRUNCATED:      return "truncated";
    case RGXSITE_INTEGRITY_FAIL: return "asset integrity failure";
    case RGXSITE_SITEID_FAIL:    return "content-address mismatch";
    case RGXSITE_NO_ENTRY:       return "no entry asset";
    default:                     return "?";
    }
}

/* ---- .rgxui declarative UI renderer ------------------------------------- */
/* Extract a double-quoted string from `line` into out (NUL-terminated). */
static const char *quoted(const char *line, char *out, size_t max) {
    const char *p = line;
    while (*p && *p != '"') p++;
    if (*p != '"') { out[0] = '\0'; return line; }
    p++;
    size_t n = 0;
    while (*p && *p != '"' && n + 1 < max) out[n++] = *p++;
    out[n] = '\0';
    if (*p == '"') p++;
    return p;              /* returns position after the closing quote */
}

static bool starts(const char *s, const char *pfx) {
    while (*pfx) { if (*s++ != *pfx++) return false; }
    return true;
}

static void render_rgxui(const char *name, const char *origin,
                         const uint8_t *ui, uint32_t len) {
    render_begin_page(name, origin);

    char lbuf[192], q[160];
    uint32_t i = 0;
    while (i < len) {
        uint32_t j = i;
        while (j < len && ui[j] != '\n') j++;
        uint32_t n = j - i;
        if (n > sizeof(lbuf) - 1) n = sizeof(lbuf) - 1;
        k_memcpy(lbuf, &ui[i], n); lbuf[n] = '\0';
        i = j + 1;

        char *s = lbuf;
        while (*s == ' ' || *s == '\t') s++;

        if (starts(s, "text")) {
            quoted(s, q, sizeof(q));
            render_line(q);
        } else if (starts(s, "link")) {
            const char *rest = quoted(s, q, sizeof(q));
            while (*rest == ' ') rest++;
            render_link(q, rest);
        } else if (starts(s, "button")) {
            const char *rest = quoted(s, q, sizeof(q));
            while (*rest == ' ') rest++;
            render_button(q, rest, -1);
        }
        /* title/panel/blank: structural */
    }
    render_end_page();
}

/* ---- package verification (no output; pure check) ----------------------- */
static rgxsite_status verify_pkg(const uint8_t *pkg, uint32_t len,
                                 uint16_t *entry_out, uint8_t id_out[32]) {
    if (len < HDR_SIZE) return RGXSITE_TRUNCATED;
    if (!(pkg[0] == 'R' && pkg[1] == 'G' && pkg[2] == 'X' && pkg[3] == 'S')) return RGXSITE_BAD_MAGIC;
    if (rd16(pkg + 4) != 1) return RGXSITE_BAD_VERSION;

    uint16_t n_assets = rd16(pkg + 6);
    uint16_t entry    = rd16(pkg + 8);
    if (n_assets == 0 || n_assets > MAX_ASSETS) return RGXSITE_TRUNCATED;
    if ((uint64_t)HDR_SIZE + (uint64_t)n_assets * DESC_SIZE > len) return RGXSITE_TRUNCATED;
    if (entry >= n_assets) return RGXSITE_NO_ENTRY;

    /* Verify every asset's SHA3-256 and gather the hashes for the site_id. */
    uint8_t gathered[MAX_ASSETS * 32];
    for (uint16_t a = 0; a < n_assets; a++) {
        const uint8_t *d = pkg + HDR_SIZE + (uint32_t)a * DESC_SIZE;
        uint32_t dlen = rd32(d + 48);
        uint32_t doff = rd32(d + 52);
        if ((uint64_t)doff + dlen > len) return RGXSITE_TRUNCATED;
        uint8_t h[32];
        rogex_sha3_256(pkg + doff, dlen, h);
        if (!mem_eq(h, d + 56, 32)) return RGXSITE_INTEGRITY_FAIL;
        k_memcpy(&gathered[a * 32], d + 56, 32);
    }
    uint8_t computed_id[32];
    rogex_sha3_256(gathered, (uint32_t)n_assets * 32, computed_id);
    if (!mem_eq(computed_id, pkg + 92, 32)) return RGXSITE_SITEID_FAIL;

    if (entry_out) *entry_out = entry;
    if (id_out) k_memcpy(id_out, computed_id, 32);
    return RGXSITE_OK;
}

rgxsite_status rgxsite_open_and_render(const uint8_t *pkg, uint32_t len) {
    uint16_t entry;
    uint8_t id[32];
    rgxsite_status s = verify_pkg(pkg, len, &entry, id);
    if (s != RGXSITE_OK) return s;

    /* Render the page first (in graphics mode this clears the screen), then
       print the verified content-address underneath it. */
    const uint8_t *ed = pkg + HDR_SIZE + (uint32_t)entry * DESC_SIZE;
    render_rgxui((const char *)(pkg + 12), (const char *)(pkg + 44),
                 pkg + rd32(ed + 52), rd32(ed + 48));

    console_write("  verified rgxsite  site_id=sha3:");
    static const char hx[] = "0123456789abcdef";
    for (int b = 0; b < 8; b++) { console_putc(hx[id[b] >> 4]); console_putc(hx[id[b] & 0xf]); }
    console_write("  assets="); console_write_dec(rd16(pkg + 6)); console_putc('\n');
    return RGXSITE_OK;
}

/* Boot self-test: the embedded site must verify, and flipping one byte of it
   must be rejected as an integrity failure. Returns true on PASS. */
bool rgxsite_selftest(void) {
    const uint8_t *pkg = SITE_SOCIAL;
    uint32_t len = SITE_SOCIAL_LEN;
    if (verify_pkg(pkg, len, NULL, NULL) != RGXSITE_OK) return false;

    static uint8_t copy[4096];
    if (len > sizeof(copy)) return true;      /* skip if too big for scratch */
    k_memcpy(copy, pkg, len);
    copy[len - 1] ^= 0x01;                     /* corrupt the last asset byte */
    return verify_pkg(copy, len, NULL, NULL) == RGXSITE_INTEGRITY_FAIL;
}

/* ---- built-in embedded sites -------------------------------------------- */
struct embedded { const uint8_t *pkg; uint32_t len; };
static const struct embedded EMBEDDED[] = {
    { SITE_SOCIAL, SITE_SOCIAL_LEN },
};
#define N_EMBEDDED (sizeof(EMBEDDED) / sizeof(EMBEDDED[0]))

bool rgxsite_try(const char *url) {
    for (size_t i = 0; i < N_EMBEDDED; i++) {
        const char *origin = (const char *)(EMBEDDED[i].pkg + 44);
        if (starts(url, origin)) {
            rgxsite_status s = rgxsite_open_and_render(EMBEDDED[i].pkg, EMBEDDED[i].len);
            if (s != RGXSITE_OK) {
                console_write("  rgxsite load refused: ");
                console_write(rgxsite_status_str(s)); console_putc('\n');
            }
            return true;
        }
    }
    return false;
}
